import subprocess
subprocess.run(["g++", "-O3", "solve.cpp"])
res = subprocess.run(["./a.out"], capture_output=True, text=True)
print(res.stdout)

from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
import itertools

V = 15
E = 27
L = 27

edges = []
for g in range(5):
    edges.append((g*3 + 0, g*3 + 1))
    edges.append((g*3 + 1, g*3 + 2))
    edges.append((g*3 + 0, g*3 + 2))
for g in range(4):
    for i in range(3):
        edges.append((g*3 + i, (g+1)*3 + i))

def var_x(v, l):
    return v * (L + 1) + l + 1

def var_y(e, d):
    return V * (L + 1) + e * L + d

solver = Glucose4()

# Exactly one label per vertex
for v in range(V):
    vars_v = [var_x(v, l) for l in range(L + 1)]
    solver.add_clause(vars_v)
    for i in range(len(vars_v)):
        for j in range(i + 1, len(vars_v)):
            solver.add_clause([-vars_v[i], -vars_v[j]])

# At most one vertex per label
for l in range(L + 1):
    vars_l = [var_x(v, l) for v in range(V)]
    for i in range(len(vars_l)):
        for j in range(i + 1, len(vars_l)):
            solver.add_clause([-vars_l[i], -vars_l[j]])

# Exactly one distance per edge
for e in range(E):
    vars_e = [var_y(e, d) for d in range(1, L + 1)]
    solver.add_clause(vars_e)
    for i in range(len(vars_e)):
        for j in range(i + 1, len(vars_e)):
            solver.add_clause([-vars_e[i], -vars_e[j]])

# At most one edge per distance
for d in range(1, L + 1):
    vars_d = [var_y(e, d) for e in range(E)]
    for i in range(len(vars_d)):
        for j in range(i + 1, len(vars_d)):
            solver.add_clause([-vars_d[i], -vars_d[j]])

# Link x and y
# y_{e, d} -> OR_l (x_{u, l} AND x_{v, l+d}) OR (x_{u, l+d} AND x_{v, l})
# Actually, if x_{u, l} and x_{v, l+d}, then y_{e, d} must be true.
for e_idx, (u, v) in enumerate(edges):
    for l1 in range(L + 1):
        for l2 in range(L + 1):
            if l1 != l2:
                d = abs(l1 - l2)
                # x_{u, l1} AND x_{v, l2} -> y_{e, d}
                solver.add_clause([-var_x(u, l1), -var_x(v, l2), var_y(e_idx, d)])

# Symmetry breaking
# V[0] < V[1] < V[2]
for l1 in range(L + 1):
    for l2 in range(l1 + 1):
        solver.add_clause([-var_x(0, l1), -var_x(1, l2)])
        solver.add_clause([-var_x(1, l1), -var_x(2, l2)])

# V[0] < 14
for l in range(14, L + 1):
    solver.add_clause([-var_x(0, l)])

# Reverse symmetry: V[0] < V[14]
# Wait, V[0] and V[14] are not necessarily symmetric.
# The graph is symmetric by reversing the cliques: 0<->4, 1<->3, 2<->2.
# And within cliques, we can permute vertices.
# But the edges between cliques are (g*3+i, (g+1)*3+i).
# So if we reverse the cliques, vertex g*3+i maps to (4-g)*3+i.
# So clique 0 maps to clique 4.
# To break this symmetry, we can enforce min(clique 0) < min(clique 4).
# Since V[0] < V[1] < V[2], V[0] is min(clique 0).
# So V[0] < min(V[12], V[13], V[14]).
for l1 in range(L + 1):
    for l2 in range(l1 + 1):
        solver.add_clause([-var_x(0, l1), -var_x(12, l2)])
        solver.add_clause([-var_x(0, l1), -var_x(13, l2)])
        solver.add_clause([-var_x(0, l1), -var_x(14, l2)])

print("Solving...")
if solver.solve():
    print("SAT")
    model = solver.get_model()
    labels = [-1] * V
    for v in range(V):
        for l in range(L + 1):
            if model[var_x(v, l) - 1] > 0:
                labels[v] = l
    print(labels)
else:
    print("UNSAT")
